import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve o que ele definiu."""
    return runpy.run_path("solucao.py")


class TestAbrirATuplaEmNomes(unittest.TestCase):
    def test_somar_dupla_soma_os_dois_itens(self):
        """somar_dupla devolve a soma dos dois itens da tupla"""
        self.assertEqual(rodar()["somar_dupla"]((10, 20)), 30)

    def test_somar_dupla_com_outros_valores(self):
        """somar_dupla devolve a soma com outros valores"""
        self.assertEqual(rodar()["somar_dupla"]((5, 6)), 11)

    def test_somar_dupla_com_valores_iguais(self):
        """somar_dupla devolve a soma de dois valores iguais"""
        self.assertEqual(rodar()["somar_dupla"]((4, 4)), 8)

